(function(root){
'use strict';
const required=['instruction.md','task.toml','README.md','environment/Dockerfile','solution/solve.sh','tests/test.sh','tests/Dockerfile'];
function pathIssue(p){if(!p||p.startsWith('/')||p.includes('\\')||p.split('/').some(x=>!x||x==='.'||x==='..'))return 'Unsafe path: '+p;const parts=p.split('/');if(!['environment','solution','tests','authoring'].includes(parts[0])&&!['instruction.md','task.toml','README.md'].includes(p))return 'Unapproved root entry: '+p;if(parts.some(x=>x==='cheat'||/^docker-compose(?:\.|$)/i.test(x)||/^compose\.ya?ml$/i.test(x)))return 'Prohibited bundle entry: '+p;return '';}
function scan(entries){const issues=[];for(const p of required)if(!entries.has(p)||!entries.get(p).length)issues.push('Missing or empty: '+p);for(const p of entries.keys()){const issue=pathIssue(p);if(issue)issues.push(issue);}return issues;}
function crc32(b){let c=0xffffffff;for(const x of b){c^=x;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;}
function zip(entries){if(entries.size>65535)throw Error('Too many files for ZIP');const out=[],central=[];let offset=0,size=0;const enc=new TextEncoder();for(const [path,data]of entries){if(pathIssue(path))throw Error(pathIssue(path));const name=enc.encode(path),crc=crc32(data);if(name.length>65535||data.length>0xffffffff)throw Error('ZIP size limit');const h=new Uint8Array(30+name.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);h.set(name,30);out.push(h,data);const c=new Uint8Array(46+name.length),w=new DataView(c.buffer);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,0x800,true);w.setUint16(14,33,true);w.setUint32(16,crc,true);w.setUint32(20,data.length,true);w.setUint32(24,data.length,true);w.setUint16(28,name.length,true);w.setUint32(42,offset,true);c.set(name,46);central.push(c);size+=c.length;offset+=h.length+data.length;}if(offset+size>0xffffffff)throw Error('ZIP size limit');const end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,entries.size,true);v.setUint16(10,entries.size,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return [...out,...central,end];}
root.BundleCore={required,pathIssue,scan,zip};if(typeof module!=='undefined')module.exports=root.BundleCore;
})(typeof window!=='undefined'?window:globalThis);
